FRAME_HIDDEN = 0
FRAME_VISIBLE = 1

slot_sprite = FRAME_HIDDEN
animation_tick = 0

function _update()
  animation_tick = (animation_tick + 1) % 12
  if animation_tick < 6 then
    slot_sprite = FRAME_HIDDEN
  else
    slot_sprite = FRAME_VISIBLE
  end
end

function _draw()
  cls(0)
  spr(slot_sprite, 16, 16)
  spr(slot_sprite, 40, 16)
